mapper.select:
SELECT s.id, s.title, s.sort_title, s.file_path, s.file_name, s.file_format, s.file_size, s.file_hash, s.fingerprint, s.duration, s.cover_path, s."year", s.bitrate, s.sample_rate, s.channels, s.bits_per_sample, s.language, s.album_id, s.track_number, s.disc_number, s.track_gain, s.track_peak, s.composer, s.lyricist, s.arranger, s.producer, s.extra_tags, s.create_time, s.update_time, sa.artist_id, a.artist_name, al.album_name FROM song s LEFT JOIN song_artist sa ON s.id = sa.song_id AND sa.sort_order = 0 LEFT JOIN artist a ON sa.artist_id = a.id LEFT JOIN album al ON s.album_id = al.id
(s.title LIKE CONCAT('%', #{keyword}, '%') OR s.file_name LIKE CONCAT('%', #{keyword}, '%') OR a.artist_name LIKE CONCAT('%', #{keyword}, '%') OR al.album_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY s.sort_title, s.create_time DESC LIMIT #{limit} OFFSET #{offset}

SELECT al.id, al.album_name AS albumName, al.album_type AS albumType, al.album_cover AS albumCover, al.introduction, al.album_year AS albumYear, al.company, al.language, al.artist_id AS artistId, al.song_count AS songCount, al.create_time AS createTime, al.update_time AS updateTime FROM album al
(al.album_name LIKE CONCAT('%', #{keyword}, '%') OR al.introduction LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY al.album_name ASC LIMIT #{limit} OFFSET #{offset}

SELECT id, artist_name AS artistName, artist_cover AS artistCover, introduction, gender, country, album_count AS albumCount, song_count AS songCount, create_time AS createTime, update_time AS updateTime FROM artist
(artist_name LIKE CONCAT('%', #{keyword}, '%') OR introduction LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY COALESCE(sort_artist_name, artist_name) ASC LIMIT #{limit} OFFSET #{offset}
